      // additional window loss: 1/mean(kaiser(202,13)) = 2.92
      wincorr = (float)FFT_SIZE / (float)(2*POINTS_COUNT) * 2.92f;
      break;
  }

  uint8_t window_size = POINTS_COUNT, offset = 0;
  uint8_t is_lowpass = FALSE;
  switch (domain_mode & TD_FUNC) {

